    55			if (t.evidenceIncomplete || t.probeFailures?.length) return "environment";
    56			if (t.status === "tool_budget_exhausted" && execution?.reportOnly) return "report-only-tool-budget";
    57			if (t.anomaly || t.reason === "worker_runaway" || t.status === "tool_budget_exhausted" || t.status === "timed_out") return "budget";
