    60			if (t.reason === "provider_failure") return "transient";
    61			if (t.status === "structured_output_failed" || t.status === "acceptance_failed") return "contract:report";
    62			if (t.reason === "launch_failure" || t.status === "invalid_request" || t.status === "duplicate_node") return "contract:delegation:launch";
